# -*- coding: utf-8 -*-
# Records and chapters 11-20, glossary.
from src_b import X, F, S, UNEP19
GW = "https://globalwitness.org/en/campaigns/land-and-environmental-defenders/in-numbers-lethal-attacks-against-defenders-since-2012"
SZ = "https://www.ohchr.org/en/documents/thematic-reports/ahrc4953-right-clean-healthy-and-sustainable-environment-non-toxic"

X("aer_x", "Alberta's oil and gas regulator is paid for entirely by the industry it regulates", "Canada", "Calgary", 2013,
  "The Alberta Energy Regulator, created in 2013, oversees oil, gas, oil sands and coal in the Canadian province that holds the third-largest proven oil reserves in the world. It is funded 100 per cent by an administrative levy on the wells, mines and facilities it regulates.",
  "The regulator's whole budget comes from the companies it is there to control.", "Alberta Energy Regulator, funding and governance statements", "https://www.aer.ca/about-aer/who-we-are", "acknowledged", "aer")
X("juliana", "Courts dismiss the young people's climate case without ever hearing the evidence", "United States", "Eugene", 2020,
  "In 2015, 21 young people sued the United States government in Oregon, arguing that its support for fossil fuels violated their constitutional rights. In January 2020 a federal appeals court accepted that the evidence showed the government had long known the danger, and dismissed the case anyway for lack of standing, ruling that the remedy was beyond a court's power. The case was dismissed again in 2024, and in March 2025 the Supreme Court declined to hear it. No trial was ever held.",
  "The judges agreed the harm was real. They ruled the people harmed had no right to bring it to court.", "Juliana v. United States, US Court of Appeals for the Ninth Circuit, 17 January 2020", "https://climatecasechart.com/case/juliana-v-united-states/", "ruling", "oct")
X("greenpeace_x", "A pipeline company wins 345 million dollars from Greenpeace over a protest", "United States", "Mandan", 2026,
  "Energy Transfer, the company behind the Dakota Access Pipeline, sued three Greenpeace organisations over the 2016 and 2017 protests at Standing Rock. In March 2025 a North Dakota jury awarded about 667 million dollars for defamation and other claims. The judge reduced the sum, and on 27 February 2026 entered a final judgment of about 345 million dollars. Greenpeace has said it cannot pay such an amount; both sides said they would appeal.",
  "A campaign group was ordered to pay a sum large enough to close it, for its part in a protest.", "Energy Transfer LP v. Greenpeace International et al., District Court of Morton County, North Dakota; final judgment 27 February 2026", "https://www.eenews.net/articles/greenpeace-ordered-to-pay-pipeline-giant-345m-in-final-ruling/", "ruling", "et")
X("chevron_ec", "Ecuador's courts award 9.5 billion dollars against Chevron; nothing is paid", "Ecuador", "Lago Agrio", 2013,
  "Texaco drilled for oil in Ecuador's northern Amazon from the 1960s to 1990 and left waste pits and contaminated water. Chevron bought Texaco in 2001. In 2011 an Ecuadorian court ordered Chevron to pay for the clean-up, and in 2013 the country's highest court fixed the sum at 9.5 billion dollars. Chevron, which had earlier argued the case should be heard in Ecuador, refused to pay, calling the judgment illegitimate, and a United States court found it had been obtained by fraud. The plaintiffs' lawyer, Steven Donziger, was disbarred and held under house arrest from August 2019.",
  "The communities won in the court the company had asked for. More than a decade later they have received nothing.", "Corte Nacional de Justicia del Ecuador, November 2013; Chevron Corp. v. Donziger, US District Court, Southern District of New York, 2014", "https://climatecasechart.com/", "ruling", "chevron")
X("bhopal", "Bhopal: a 470 million dollar settlement for the world's worst industrial disaster", "India", "Bhopal", 1989,
  "On the night of 2 December 1984, gas leaked from a pesticide plant in Bhopal owned by a subsidiary of the United States company Union Carbide. Several thousand people died within days and hundreds of thousands were injured. In 1989 Union Carbide settled all claims with the Indian government for 470 million dollars. Its chairman, Warren Anderson, was charged in India and never appeared before the court. Dow bought Union Carbide in 2001.",
  "Divided among the people harmed, the settlement came to a few hundred dollars each.", "Supreme Court of India, Union Carbide Corporation v. Union of India, 14 February 1989", "https://www.britannica.com/event/Bhopal-disaster", "settled", "dow")
X("ogoni", "The UN finds Ogoniland will take decades to clean; work begins eight years later", "Nigeria", "Bori", 2011,
  "At Nigeria's request, the UN Environment Programme surveyed Ogoniland in the Niger Delta, where Shell had pumped oil until 1993. Its 2011 report found drinking water contaminated with benzene at many times the safe level and concluded that restoring the land could take 25 to 30 years, starting with a fund of 1 billion dollars. Clean-up work on the ground did not begin until 2019.",
  "The damage was measured and the cost was named. Then eight years passed before anyone started.", "UN Environment Programme, Environmental Assessment of Ogoniland, August 2011", "https://www.unep.org/topics/disasters-and-conflicts/country-presence/nigeria/environmental-assessment-ogoniland-report", "inquiry", "shell")
X("shell_nl", "A court orders Shell to cut emissions by 45 per cent; an appeal court cancels the order", "Netherlands", "The Hague", 2024,
  "In May 2021 the district court in The Hague ordered Shell to cut the carbon emissions of its operations and of the fuels it sells by 45 per cent by 2030, compared with 2019. On 12 November 2024 the Hague appeal court overturned that order. It accepted that Shell has a duty to limit emissions, and ruled that no agreed standard existed that would let a court fix a specific percentage for one company.",
  "For three years one oil company was under a court order to cut its emissions. Then it was not.", "Milieudefensie et al. v. Shell plc, Gerechtshof Den Haag, 12 November 2024", "https://climatecasechart.com/non-us-case/milieudefensie-et-al-v-royal-dutch-shell-plc/", "ruling", "shell")
X("mariana", "BHP found liable for a dam collapse in Brazil, ten years later and in London", "Brazil", "Mariana", 2025,
  "On 5 November 2015 the Fundão waste dam, owned by Samarco, a company half-owned by BHP and half by Vale, collapsed near Mariana in Brazil. Nineteen people died and mining waste travelled hundreds of kilometres down the River Doce to the sea. More than 600,000 claimants sued BHP in England. On 14 November 2025 the High Court in London found BHP liable under Brazilian law, ruling that raising the dam's height when it was unsafe was the direct cause. The amount to be paid has not been decided, and BHP said it would appeal.",
  "It took ten years and a court on another continent to rule on who was responsible.", "Município de Mariana v. BHP Group, [2025] EWHC 3001 (TCC), 14 November 2025", "https://www.judiciary.uk/judgments/municipio-de-mariana-v-bhp-group/", "ruling", "bhp")
X("ets", "European industry earns tens of billions from free pollution permits", "Belgium", "Brussels", 2021,
  "The European Union's carbon market, opened in 2005, requires factories and power plants to hold a permit for each tonne of carbon dioxide. Heavy industry was given most of its permits free, to stop it moving abroad. A study by the consultancy CE Delft for the campaign group Carbon Market Watch estimated that between 2008 and 2019 heavy industry in 19 countries made up to 50 billion euros in extra profit from the system, by selling spare permits and by charging customers for permits it had received free.",
  "A system built to make polluters pay ended up paying some of the largest ones.", "CE Delft for Carbon Market Watch, Additional profits of sectors and firms from the EU ETS 2008-2019, 2021", "https://carbonmarketwatch.org/publications/additional-profits-of-sectors-and-firms-from-the-eu-ets/", "inquiry", "eu_env")
X("liberia", "A Dubai company seeks carbon rights over a tenth of Liberia", "Liberia", "Monrovia", 2023,
  "In 2023 a draft agreement became public between Liberia's government and Blue Carbon, a company founded in Dubai the previous year and chaired by a member of the emirate's ruling family. It would have given the company exclusive rights for 30 years to produce and sell carbon credits from about one million hectares of Liberian forest, roughly a tenth of the country's land. Liberian civil society groups said the people living in those forests had not been consulted, as Liberian law requires.",
  "The right to pollute elsewhere was to be manufactured from a tenth of another country's land.", "Reporting by Mongabay and the Associated Press on the Liberia-Blue Carbon memorandum of understanding, 2023", "https://news.mongabay.com/2023/08/liberia-set-to-concede-forestland-to-uae-firm-in-carbon-offset-deal/", "reported", who="Blue Carbon LLC")
X("probo", "A trader's toxic waste is dumped around Abidjan", "Cote d'Ivoire", "Abidjan", 2006,
  "In August 2006 the Probo Koala, a ship registered in Panama and chartered by the commodity trader Trafigura, unloaded waste at Abidjan after a company in Amsterdam had quoted a much higher price to treat it. A local contractor dumped it at about a dozen sites around the city. Ivorian authorities recorded deaths and tens of thousands of people sought medical care. In 2007 Trafigura paid the Ivorian government about 198 million dollars without admitting liability; a Dutch court later fined the company for illegally exporting the waste.",
  "Treating the waste properly in Europe had a price. Dumping it in Africa was cheaper.", "Amnesty International and Greenpeace Netherlands, The Toxic Truth, 2012", "https://www.amnesty.org/en/documents/afr31/002/2012/en/", "ruling", "trafigura")
X("pesticides", "European countries export 81,000 tonnes of pesticides banned on their own farms", "Switzerland", "Zurich", 2020,
  "Using export notifications obtained under freedom of information laws, Public Eye and Greenpeace's investigative unit Unearthed found that in 2018 European Union countries, which then included the United Kingdom, approved the export of 81,615 tonnes of pesticides containing 41 chemicals banned for use in the Union. The United Kingdom, Italy, Germany, the Netherlands, France, Spain and Belgium were the largest exporters; Brazil, Ukraine, Morocco, Mexico and South Africa were among the main destinations.",
  "The chemicals were judged too dangerous to spray in Europe, and remained legal to make there and sell abroad.", "Public Eye and Unearthed, Banned in Europe, 10 September 2020", "https://www.publiceye.ch/en/topics/pesticides/banned-in-europe", "inquiry", "publiceye")
X("sacrifice", "The UN's expert names the world's sacrifice zones", "Switzerland", "Geneva", 2022,
  "In a 2022 report to the Human Rights Council, the UN Special Rapporteur on human rights and the environment described sacrifice zones: places where residents suffer severe harm to health from living in pollution hotspots. The report named sites on every inhabited continent, among them Kabwe in Zambia, La Oroya in Peru, Norilsk in Russia, Quintero-Puchuncaví in Chile, Bor in Serbia, Taranto in Italy and Cancer Alley in the United States.",
  "These are not accidents. They are places where pollution was allowed to concentrate.", "UN Special Rapporteur on human rights and the environment, The right to a clean, healthy and sustainable environment: non-toxic environment, A/HRC/49/53, 2022", SZ, "inquiry", "ohchr")
X("lancet", "Pollution kills about nine million people a year", "United Kingdom", "London", 2022,
  "The Lancet Commission on pollution and health estimated that pollution caused about nine million premature deaths in 2019, one death in every six worldwide. More than 90 per cent were in low- and middle-income countries. Deaths from modern forms of pollution, such as outdoor air pollution and toxic chemicals, had risen by 66 per cent since 2000.",
  "One death in six. Most of the pollution involved was released by sites operating with permission.", "Fuller et al., Pollution and health: a progress update, The Lancet Planetary Health, 2022", "https://www.thelancet.com/journals/lanplh/article/PIIS2542-5196(22)00090-0/fulltext", "inquiry", who="Lancet Commission on pollution and health")
X("taranto", "Europe's human rights court rules Italy failed the people of Taranto", "Italy", "Taranto", 2019,
  "The Ilva steelworks at Taranto, in southern Italy, was the largest in Europe. Italian governments repeatedly passed decrees to keep it running after prosecutors tried to shut its most polluting sections. In January 2019 the European Court of Human Rights ruled, in a case brought by 180 residents, that Italy had failed to protect their health and had left them with no effective way to obtain a clean-up.",
  "Each time the courts moved to stop the pollution, the government passed a decree to keep the plant open.", "Cordella and Others v. Italy, European Court of Human Rights, 24 January 2019", "https://hudoc.echr.coe.int/eng?i=001-189645", "ruling", "ecthr")
X("laoroya", "The Americas' human rights court rules against Peru over La Oroya", "Peru", "La Oroya", 2024,
  "A metal smelter has operated at La Oroya in the Peruvian Andes since 1922, and studies found that nearly all the town's children had dangerous levels of lead in their blood. In a judgment published in March 2024, the Inter-American Court of Human Rights found Peru responsible for violating residents' rights to a healthy environment, health and life, because it had failed to regulate and supervise the smelter.",
  "A century of smelting, and the first binding ruling for the people who breathed it came in 2024.", "Inhabitants of La Oroya v. Peru, Inter-American Court of Human Rights, judgment of 27 November 2023, notified March 2024", "https://www.corteidh.or.cr/docs/casos/articulos/seriec_511_ing.pdf", "ruling", "iacthr")
X("gw2025", "2,375 land and environmental defenders killed or disappeared since 2012", "United Kingdom", "London", 2026,
  "Global Witness has recorded every killing and long-term disappearance of a land or environmental defender it could verify since 2012. Its latest report counts at least 124 killed in 2025 and 2,375 since 2012. In 2025, 85 per cent of the killings were in Latin America, and Colombia and Brazil together accounted for 52 per cent. Forty-four of those killed were Indigenous. The organisation says its figures are an undercount, because many cases are never reported.",
  "They were killed for asking that land and environmental law be applied where they lived.", "Global Witness, annual defenders report, 2026", GW, "inquiry", "globalwitness")
X("berta", "A dam company's former president is convicted over the murder of Berta Cáceres", "Honduras", "La Esperanza", 2021,
  "Berta Cáceres, a leader of the Lenca people and co-founder of the organisation COPINH, led the opposition to the Agua Zarca dam on the Gualcarque River in Honduras. She was shot dead at her home in La Esperanza on 2 March 2016. Seven men were convicted in 2018. In July 2021 a Honduran court found Roberto David Castillo, a former military intelligence officer who had been president of the dam company DESA, guilty as a co-collaborator in planning the murder.",
  "The man who ran the company building the dam helped plan the killing of the woman who opposed it.", "Tribunal de Sentencia con Competencia Nacional, Honduras, verdict of 5 July 2021", "https://www.theguardian.com/world/2021/jul/05/berta-caceres-assassination-roberto-david-castillo-found-guilty", "ruling", "copinh")
X("sarowiwa", "Nigeria hangs Ken Saro-Wiwa and eight others; Shell later settles for 15.5 million dollars", "Nigeria", "Port Harcourt", 1995,
  "Ken Saro-Wiwa, a writer, led the Movement for the Survival of the Ogoni People, which campaigned against oil pollution in the Niger Delta. Nigeria's military government tried him and eight others before a special tribunal and hanged them in Port Harcourt on 10 November 1995. Their families sued Shell in New York, alleging the company had been complicit. In 2009, days before trial, Shell agreed to pay 15.5 million dollars, without admitting liability.",
  "Nine men who campaigned against oil pollution were executed. The company they campaigned against paid, and admitted nothing.", "Wiwa v. Royal Dutch Petroleum Co., US District Court, Southern District of New York, settlement of 8 June 2009", "https://ccrjustice.org/home/what-we-do/our-cases/wiwa-et-al-v-royal-dutch-petroleum-et-al", "settled", "shell")
X("urgenda_x", "The Dutch Supreme Court orders the government to cut emissions faster", "Netherlands", "The Hague", 2019,
  "The Urgenda Foundation and about 900 citizens sued the Dutch state in 2013. On 20 December 2019 the Supreme Court of the Netherlands confirmed that the government had a duty under human rights law to cut greenhouse gas emissions by at least 25 per cent from 1990 levels by the end of 2020. It was the first time a country's highest court had ordered its government to reduce emissions by a set amount. The government then cut the output of coal power plants.",
  "Citizens took their own government to court over the climate and won at the highest level.", "State of the Netherlands v. Urgenda Foundation, Hoge Raad, 20 December 2019", "https://www.urgenda.nl/en/themas/climate-case/", "ruling", "urgenda")
X("icj_ao", "The world's highest court advises that countries must protect the climate", "Netherlands", "The Hague", 2025,
  "A campaign begun by law students in the Pacific and taken up by the government of Vanuatu led the UN General Assembly to ask the International Court of Justice what countries owe one another on climate change. On 23 July 2025 the court advised, unanimously, that countries have binding duties to protect the climate system, that these include regulating private companies, and that failing to act, including by subsidising or licensing fossil fuels, can be a wrongful act for which a country may owe reparation. An advisory opinion is not directly enforceable, but courts everywhere can rely on it.",
  "A question first asked by students on small islands was answered by the highest court there is.", "International Court of Justice, Obligations of States in respect of Climate Change, advisory opinion of 23 July 2025", "https://www.icj-cij.org/case/187", "ruling", "icj")
X("loscedros", "Ecuador's top court stops a mine because the forest has rights", "Ecuador", "Los Cedros", 2021,
  "Ecuador's 2008 constitution was the first in the world to give nature legal rights of its own. In November 2021 the Constitutional Court applied those rights to the Los Cedros cloud forest, cancelling the mining permits that a state company and a Canadian partner held there. In a referendum in August 2023, about 59 per cent of Ecuadorian voters also chose to stop oil drilling in a block of Yasuní National Park.",
  "Here the question was not how much damage to permit. The court ruled that none could be.", "Corte Constitucional del Ecuador, case 1149-19-JP/21, 10 November 2021", "https://www.corteconstitucional.gob.ec/", "ruling", "cc_ec")
X("panama", "Panama's Supreme Court strikes down a copper mine's contract after weeks of protest", "Panama", "Cobre Panamá", 2023,
  "In October 2023 Panama's legislature approved a new 20-year contract for Cobre Panamá, one of the largest copper mines in the world, owned by the Canadian company First Quantum Minerals. Weeks of nationwide protests and road blockades followed. On 28 November 2023 the Supreme Court ruled unanimously that the contract was unconstitutional, and the government ordered the mine to close. The company then began arbitration claims against Panama.",
  "A whole country objected, and its highest court agreed. The company's answer was to sue.", "Corte Suprema de Justicia de Panamá, ruling of 28 November 2023", "https://www.reuters.com/world/americas/panama-top-court-rules-first-quantum-mining-contract-unconstitutional-2023-11-28/", "ruling", "fqm")

# ------------------------------------------------------------------ chapters 11-20
F(id="door", part=2, title="The Revolving Door",
  kick="People move from industry into the agencies that regulate it, and regulators are funded by those they regulate.",
  sum="Lobbying, as the last two chapters showed, works from outside the government. There is a shorter route. The people who run an environmental agency are appointed, and they can be appointed from the industry the agency regulates. When their term ends, they can return to it. This movement back and forth is called the revolving door.<br><br>A person who has spent a career working for coal or oil companies does not need to be bribed to see things as those companies do. They bring the industry's view of what is reasonable into the office that writes the rules. Their former colleagues know them and can reach them.<br><br>A second arrangement produces a similar result without any change of staff. Some regulators are paid for by fees or levies on the companies they oversee, in place of general taxation. This is presented as making the polluter pay for its own supervision. It also means the regulator's budget depends on the health of the industry.<br><br>Neither arrangement breaks a law. Both narrow the distance that is supposed to exist between a regulator and the regulated. Chapter 3 showed the same thing at the top of the chain, where oil company men chaired the climate talks.",
  bridge="The first slide shows the door turning in the largest economy, in three appointments. The second shows a regulator whose budget comes entirely from industry.",
  rec="A man who sued the EPA 14 times was put in charge of it, followed by a coal lobbyist; Alberta's energy regulator is funded entirely by the industry it regulates.",
  out="Industry writes text, shapes opinion and supplies the regulators. The last chapter of this part looks at rules that never pass through a legislature at all.",
  roles=["Where the regulator sits"],
  steps=[
   S("2017 to 2019", "Washington", "United States: Three Appointments", "Regional Example: Scott Pruitt was the attorney general, or chief government lawyer, of the oil-producing state of Oklahoma. In that job he sued the Environmental Protection Agency at least 14 times to stop its pollution rules. In 2017 he was appointed to run the agency. After he resigned in 2018 he was replaced by Andrew Wheeler, who had been a lobbyist for a coal mining company. The Department of the Interior, which leases public land for drilling and mining, was led from 2019 by David Bernhardt, who had been a lobbyist for oil and water companies. The more than 100 rule reversals described in chapter 7 were carried out under these three men.", "https://www.nytimes.com/2017/01/14/us/scott-pruitt-trump-epa-pick.html",
     add={"United States": 0}, arcs=[("Oklahoma City", "Washington")], pins=[("Washington", "EPA and Interior"), ("Oklahoma City", "Oklahoma attorney general's office")], pl=["epa_us", "doi_us", "api"], ex=["pruitt"], reg=True),
   S("2013", "Calgary", "Alberta: A Regulator Paid by Industry", "Regional Example: The Canadian province of Alberta holds the third-largest proven oil reserves in the world, most of them in the oil sands. In 2013 it created a single body, the Alberta Energy Regulator, to oversee oil, gas, oil sands and coal, including their environmental effects. The regulator is funded 100 per cent by a levy on the wells, mines and facilities it oversees. Its head office is in Calgary, the same city as the oil companies and their trade association. A regulator in this position has no money that does not come from the industry, so a smaller industry would mean a smaller regulator. The same funding model is used by other energy regulators in Canada.", "https://www.aer.ca/about-aer/who-we-are",
     add={"Canada": 0}, arcs=[("Edmonton", "Calgary")], pins=[("Calgary", "Alberta Energy Regulator; oil company head offices"), ("Edmonton", "Provincial government")], pl=["aer", "capp", "tc"], ex=["aer_x"], reg=True, z=3.4),
  ],
  src=[{"t": "Alberta Energy Regulator, Who We Are", "u": "https://www.aer.ca/about-aer/who-we-are"}])

F(id="standards", part=2, title="Rules Written Outside the Law",
  kick="Voluntary standards, certificates and paid auditors stand in for law, and the companies choose and pay them.",
  sum="Where the law is weak or missing, something else usually fills the space: a private standard. A standard is a written set of requirements. A certifier is a body that checks a company against the standard and issues a certificate. An auditor is the person sent to do the checking. A label on a product, or a line in a company report saying a site is certified, tells the public that someone independent has looked.<br><br>These systems share a design. The standard is written by a private organisation, often with the industry concerned sitting on its board. Compliance is voluntary. And the company being checked chooses the certifier and pays its bill. A certifier that fails too many clients will lose them to one that does not.<br><br>Governments rely on these private systems more and more. Laws refer to them, public buyers require them, and regulators accept an auditor's signature in place of an inspection. The effect is that part of the job of making and enforcing environmental rules has moved to bodies no voter elected and no court supervises.<br><br>The same thing happens at sea, where the rules are written by an international agency, but the governments with the largest voice there are countries that sell their flag to shipowners.",
  bridge="The slides begin with the most common environmental certificate in the world and what it does and does not promise. Next is the shipping agency in London and the flags that fill it. The third and fourth are a carbon credit certifier and a dam safety auditor, each tested against what actually happened.",
  rec="A certificate for management systems says nothing about emissions, the largest flag states rent their flags, most audited rainforest credits were found empty, and a certified dam killed 270 people.",
  out="That ends the part on who writes the rules. Whatever their origin, rules meet their real test when someone tries to rely on them in court. That is the next part.",
  roles=["Where the standard-setter or certifier is based", "Where the flag is registered or the harm fell"],
  steps=[
   S("1996", "Geneva", "A Certificate for Having a System", "The International Organization for Standardization, based in Geneva, is a private federation of national standards bodies. Its environmental standard, ISO 14001, was first published in 1996, and hundreds of thousands of sites around the world now hold the certificate. What it certifies is that a company has an environmental management system: a written policy, named responsibilities and a process for review. It does not set any limit on what the company may emit or discharge. A site can pollute heavily and be certified, provided its paperwork is in order. Companies display the certificate to customers and regulators, many of whom take it to mean more than it does.", "https://www.iso.org/standards/popular/iso-14000-family",
     add={"Switzerland": 0}, pins=[("Geneva", "ISO")], pl=["iso", "wbcsd", "icmm"], z=3.2),
   S("2018", "London", "At Sea: Flags for Rent", "Ships cause oil spills and air pollution and carry most of the world's trade. Their rules are written at the International Maritime Organization in London, whose members are governments. A ship follows the law of the country whose flag it flies, and an owner can buy a flag from a country it has no other link to. Panama, Liberia and the Marshall Islands together register more than 40 per cent of the world's shipping capacity. The Marshall Islands' registry is run by a private company from Virginia, in the United States. In 2018 Transparency International reported that such registries can represent their flag state at the organisation. So the governments with the most weight over shipping's pollution rules earn their income from keeping shipowners content.", "https://www.transparency.org/en/publications/governance-at-the-imo-the-case-for-reform",
     add={"United Kingdom": 0, "Panama": 1, "Liberia": 1, "Marshall Islands": 1}, arcs=[("Panama City", "London"), ("Monrovia", "London"), ("Majuro", "Reston"), ("Reston", "London")], pins=[("London", "International Maritime Organization"), ("Panama City", "Panama flag"), ("Monrovia", "Liberia flag"), ("Majuro", "Marshall Islands flag"), ("Reston", "Registry operator")], pl=["imo", "ics", "iri"], ex=["flags"], w=0, z=1.4),
   S("2023", "Washington", "Carbon Credits: Certified, Then Tested", "A carbon credit is a certificate saying that one tonne of carbon dioxide was kept out of the air somewhere, for example by protecting a forest that would otherwise have been cut. A company buys credits and subtracts them from its own emissions. The largest certifier of such credits is Verra, a non-profit organisation in Washington. In January 2023 three news organisations published an analysis of scientific studies of Verra's rainforest projects. It concluded that more than 90 per cent of the credits examined did not represent real reductions, mostly because the forests had not been in the danger claimed. Verra rejected the findings. The buyers had included some of the world's largest companies, which had used the credits to describe themselves as carbon neutral.", "https://www.theguardian.com/environment/2023/jan/18/revealed-forest-carbon-offsets-biggest-provider-worthless-verra-aoe",
     add={"United States": 0}, pins=[("Washington", "Verra")], pl=["verra", "goldstandard", "ieta"], ex=["verra_x"]),
   S("2018 to 2019", "Brumadinho", "Brazil: The Dam Was Certified Stable", "Regional Example: Mines store their waste as mud behind earth dams. Brazilian law required the mining company Vale to have its dams declared stable by an outside auditor. For the dam at its Córrego do Feijão mine in Brumadinho, Vale hired the Brazilian branch of TÜV SÜD, a German inspection company based in Munich. In September 2018 the auditor signed the declaration. On 25 January 2019 the dam collapsed. The mud buried the mine's canteen at lunchtime and the valley below, and 270 people died. Brazilian prosecutors charged staff of both companies. The auditor had been selected and paid by the company whose dam it was judging, which is how the system was designed to work.", "https://www.bbc.com/news/business-51220373",
     add={"Brazil": 1, "Germany": 0}, arcs=[("Munich", "Brumadinho"), ("Rio de Janeiro", "Brumadinho")], pins=[("Brumadinho", "Dam collapse, 25 January 2019"), ("Munich", "TÜV SÜD"), ("Rio de Janeiro", "Vale")], pl=["tuvsud", "vale"], ex=["brumadinho"], reg=True),
  ],
  src=[{"t": "Greenpeace International, Destruction: Certified (2021)", "u": "https://www.greenpeace.org/international/publication/46812/destruction-certified/"}])

F(id="courthouse", part=3, title="Getting Through the Courthouse Door",
  kick="Before a court will hear an environmental case, the people harmed must prove they are allowed to bring it, and they can be sued for speaking.",
  sum="The story has reached the point where a law exists and has been broken, or where a government is failing to act, and someone decides to go to court. This part of the map looks at what happens next.<br><br>The first obstacle is called standing. A court will hear only a person who can show that they have been harmed in a particular way, that the party they are suing caused the harm, and that a court order could repair it. Environmental harm fits badly into this test. Pollution spreads. It harms many people a little, has many sources, and may take decades to show. Courts have used standing to dismiss cases without examining the evidence at all.<br><br>The second obstacle is cost, which works in both directions. A community rarely has the money for years of litigation. A company does, and it can also sue its critics. A lawsuit brought mainly to exhaust and frighten an opponent is known as a SLAPP, a strategic lawsuit against public participation. The claim does not need to succeed. The expense of defending it is the purpose.<br><br>Compare this with chapter 4. A company that dislikes an environmental rule has a special court with no standing test. A person who wants the rule applied may not get through the door.",
  bridge="The first two slides are cases dismissed at the door in the United States, one brought by a village and one by young people. The third and fourth show the law used in the other direction: against a campaign group, and against a lawyer who had won.",
  rec="A drowning Alaskan village and 21 young people were told they had no standing; a pipeline company won 345 million dollars from Greenpeace; the lawyer who beat Chevron in Ecuador was confined to his home.",
  out="Many cases never get in, and those who bring them can be ruined. The next chapter follows cases that did get in, and were won, to see what winning delivered.",
  roles=["Where the case was heard", "Where the harm was"],
  steps=[
   S("2008 to 2013", "Kivalina", "A Village With No Right to Sue", "Regional Example: Kivalina is an Iñupiat village of about 400 people on a strip of land off the north-west coast of Alaska. The sea ice that used to shield it from storms now forms later each year, and the shore is washing away. In 2008 the village sued ExxonMobil and other energy companies for the cost of moving, estimated at up to 400 million dollars. A federal court in California dismissed the case. It ruled that the question was a political one for the other branches of government to settle, and that the village lacked standing because its loss could not be traced to these particular companies. The appeal failed and in 2013 the Supreme Court declined to hear it. No court ever weighed the evidence.", "https://climatecasechart.com/case/native-village-of-kivalina-v-exxonmobil-corp/",
     add={"United States": 0}, arcs=[("Kivalina", "San Francisco")], pins=[("Kivalina", "Kivalina"), ("San Francisco", "Federal court")], pl=["exxon", "scotus"], reg=True, z=2.2),
   S("2015 to 2025", "Eugene", "Twenty-One Young People, No Trial", "Regional Example: In 2015, 21 children and young adults sued the United States government in Eugene, Oregon. They argued that by promoting fossil fuels while knowing the consequences, it had violated their constitutional right to life and liberty. The government fought for years to prevent a trial. In January 2020 an appeal court ruled against the young people on standing. The judges wrote that the evidence showed the government had long known of the danger, and then held that no court had the power to order the remedy the plaintiffs asked for. In March 2025 the Supreme Court declined to hear the case, ending it after ten years. A similar case under a state constitution reached a different result, as the final part shows.", "https://climatecasechart.com/case/juliana-v-united-states/",
     add={"United States": 0}, arcs=[("Eugene", "San Francisco"), ("San Francisco", "Washington")], pins=[("Eugene", "Juliana v. United States, filed 2015")], pl=["oct", "scotus"], ex=["juliana"], reg=True, z=2.8),
   S("2017 to 2026", "Mandan", "A Protest, and a 345 Million Dollar Judgment", "Regional Example: Chapter 9 described the protests at Standing Rock against the Dakota Access Pipeline. The pipeline's owner, Energy Transfer, sued Greenpeace, first in federal court, where the case was dismissed, and then in a North Dakota state court. It accused the group of defamation and of organising the protests. In March 2025 a jury in Mandan awarded about 667 million dollars. The judge reduced this, and on 27 February 2026 entered a final judgment of about 345 million. Greenpeace says it cannot pay and is appealing. Whatever happens on appeal, every campaign group now knows the possible price of supporting a protest against a pipeline.", "https://www.eenews.net/articles/greenpeace-ordered-to-pay-pipeline-giant-345m-in-final-ruling/",
     add={"United States": 0, "Netherlands": 1}, arcs=[("Dallas", "Mandan"), ("Mandan", "Amsterdam")], pins=[("Mandan", "Morton County court"), ("Dallas", "Energy Transfer"), ("Amsterdam", "Greenpeace International")], pl=["et", "greenpeace"], ex=["greenpeace_x"], reg=True),
   S("1993 to 2021", "Lago Agrio", "Ecuador: The Winning Lawyer Confined", "Regional Example: From the 1960s to 1990 the United States oil company Texaco drilled in Ecuador's northern Amazon and left open pits of oil waste. Residents sued in New York in 1993. Texaco argued the case belonged in Ecuador, and it was moved there. Chevron bought Texaco in 2001. In 2011 an Ecuadorian court ruled against Chevron, and the country's highest court later set the sum at 9.5 billion dollars. Chevron refused to pay and sued the plaintiffs' lawyer, Steven Donziger, in New York, where a judge found the judgment had been obtained through fraud. Donziger was disbarred, held under house arrest from August 2019 and sentenced to six months for contempt of court. The waste pits remain.", "https://climatecasechart.com/",
     add={"Ecuador": 1, "United States": 0}, arcs=[("Lago Agrio", "Quito"), ("Houston", "New York"), ("New York", "Lago Agrio")], pins=[("Lago Agrio", "Lago Agrio oil field"), ("New York", "Chevron v. Donziger")], pl=["chevron", "cc_ec"], ex=["chevron_ec"], reg=True),
  ],
  src=[{"t": "Sabin Center for Climate Change Law, climate litigation databases", "u": "https://climatecasechart.com/"}])

F(id="unpaid", part=3, title="Winning the Case, Waiting for the Result",
  kick="Even where communities win, the money is small, the clean-up is late, or the order is later cancelled.",
  sum="Some cases do get through the door, and some are won. A judgment, though, is a piece of paper. It has to be turned into money paid, land cleaned or pollution stopped, and that step depends on the same governments and companies the earlier chapters described.<br><br>Several things commonly go wrong. The case takes so long that many of the people harmed have died before it ends. The company involved is a local subsidiary with few assets, while its parent company sits in another country and argues that it is a separate legal person. The settlement is negotiated by a government over the heads of the victims. Or a higher court reverses the order years later.<br><br>Time is money in the most literal sense here. A company that will one day have to pay a billion dollars gains from every year the payment is put off, because the money stays in its accounts earning a return. Delay is not a side effect of these cases. For the defendant it is often the strategy.<br><br>This chapter is why the earlier parts of the story matter so much. If the law reliably repaired harm after the event, weak permits and absent inspectors would count for less. It does not.",
  bridge="Four cases follow in order of time, from India in the 1980s to a London courtroom in 2025. In each, a court or an official body confirmed the harm. The slides show what the affected people had received by the date of the ruling, and how long it took.",
  rec="Bhopal's victims received a few hundred dollars each; Ogoniland's clean-up began eight years after it was costed; Shell's emissions order was cancelled; BHP was found liable ten years after its dam collapsed.",
  out="The courts, then, are slow, costly to enter and uncertain in their results. The next part looks at what has been built in the space the law leaves: markets that sell permission.",
  roles=["Where the harm was", "Where the company is based or the case was heard"],
  steps=[
   S("1984 to 1989", "Bhopal", "Bhopal: Settled Over the Victims' Heads", "Regional Example: In December 1984 a tank at a pesticide plant in Bhopal, in central India, leaked poisonous gas over the sleeping city. The plant belonged to an Indian subsidiary of Union Carbide, a United States company. Several thousand people died within days and hundreds of thousands were injured. India's government passed a law making itself the sole representative of the victims. In 1989 it accepted 470 million dollars from Union Carbide in settlement of every claim. Spread across the number of people compensated, that came to a few hundred dollars for most. The company's chairman was charged in India and never stood trial. Contaminated waste lay at the site for four decades.", "https://www.britannica.com/event/Bhopal-disaster",
     add={"India": 0, "United States": 1}, arcs=[("Midland", "Bhopal")], pins=[("Bhopal", "Bhopal, 1984"), ("Midland", "Dow, owner of Union Carbide since 2001")], pl=["dow", "moefcc"], ex=["bhopal"], reg=True),
   S("2011 to 2019", "Bori", "Ogoniland: Costed in 2011, Begun in 2019", "Regional Example: The Niger Delta in southern Nigeria has been drilled for oil since the 1950s, and Shell was its main operator. In Ogoniland, a small part of the delta, UNEP carried out a two-year scientific survey at the Nigerian government's request. Its 2011 report found oil in the soil to depths of five metres and a community drinking from wells with 900 times the safe level of benzene, a chemical that causes cancer. It concluded the clean-up could take 25 to 30 years and should start with a billion-dollar fund paid mostly by the oil companies. Contractors did not begin work on the ground until 2019. In those eight years a child born in Ogoniland had started school drinking the same water.", "https://www.unep.org/topics/disasters-and-conflicts/country-presence/nigeria/environmental-assessment-ogoniland-report",
     add={"Nigeria": 0, "United Kingdom": 1}, arcs=[("London", "Bori"), ("Abuja", "Bori")], pins=[("Bori", "Ogoniland"), ("London", "Shell")], pl=["shell", "nnpc", "nesrea", "unep"], ex=["ogoni", "sarowiwa"], reg=True, z=3.2),
   S("2021 to 2024", "The Hague", "The Netherlands: An Order Made and Unmade", "Regional Example: In May 2021 a court in The Hague did something no court had done before. In a case brought by the Dutch branch of Friends of the Earth, it ordered Shell to cut its carbon emissions, including those from the fuel it sells, by 45 per cent by 2030. Shell appealed and, later that year, moved its headquarters from The Hague to London. On 12 November 2024 the appeal court cancelled the order. It agreed that Shell has a duty to reduce emissions, and ruled that there was no accepted standard by which a court could set a number for a single company. The duty remains on paper. The number is gone.", "https://climatecasechart.com/non-us-case/milieudefensie-et-al-v-royal-dutch-shell-plc/",
     add={"Netherlands": 0, "United Kingdom": 1}, arcs=[("The Hague", "London")], pins=[("The Hague", "District court 2021; appeal court 2024"), ("London", "Shell, since 2022")], pl=["shell", "foei", "hague_ct"], ex=["shell_nl"], reg=True, z=3.6),
   S("2015 to 2025", "Mariana", "Brazil to London: Ten Years to a Finding", "Regional Example: On 5 November 2015 a dam holding iron ore waste collapsed near Mariana, in the Brazilian state of Minas Gerais. Nineteen people died. The mud ran down the River Doce for more than 600 kilometres to the Atlantic. The dam belonged to Samarco, owned half by the Brazilian company Vale and half by BHP, the world's largest mining company. More than 600,000 people and dozens of towns sued BHP in England, where part of the company was based. English courts first refused the case, then accepted it on appeal. On 14 November 2025 the High Court found BHP liable. How much it must pay will be decided in a further trial, and BHP is appealing. Four years after Mariana, the Brumadinho dam from chapter 12 collapsed in the same state.", "https://www.judiciary.uk/judgments/municipio-de-mariana-v-bhp-group/",
     add={"Brazil": 0, "United Kingdom": 1, "Australia": 1}, arcs=[("Mariana", "London"), ("Melbourne", "Mariana")], pins=[("Mariana", "Fundão dam, 2015"), ("London", "High Court, 2025"), ("Melbourne", "BHP")], pl=["bhp", "vale", "samarco", "ibama"], ex=["mariana"], reg=True),
  ],
  src=[{"t": "UNEP, Environmental Assessment of Ogoniland (2011)", "u": "https://www.unep.org/topics/disasters-and-conflicts/country-presence/nigeria/environmental-assessment-ogoniland-report"}])

F(id="carbon", part=4, title="Selling the Right to Pollute",
  kick="Carbon markets turn a pollution limit into permits that can be given away, traded and manufactured.",
  sum="The earlier parts described rules being weakened. This part describes something different: businesses that have grown up because the rules exist.<br><br>The largest is the carbon market. The idea came from economists and was written into the Kyoto Protocol. A government sets a total amount of carbon dioxide that may be released and issues that many permits, usually called allowances. A factory needs one for each tonne it emits. A company that cuts its emissions cheaply can sell its spare allowances to one that cannot, so in theory the cuts happen wherever they cost least. A second version, called offsetting, lets a company pay for a reduction somewhere else in the world and count it as its own.<br><br>The design turns pollution into property. Once the right to emit a tonne is a thing that can be owned, a great deal depends on who is given the permits at the start, and on whether a reduction that is sold really took place. Those are decisions made by governments and certifiers under pressure from the industries concerned, by the routes the earlier chapters set out. The trade association for carbon traders is among the largest groups at each climate summit.",
  bridge="The first slide shows what happened when a government gave permits away free. The second shows a factory that was paid more for destroying a waste gas than for its actual product. The third shows the newest form of the market: one company seeking the carbon rights over a tenth of a country.",
  rec="Free permits earned European industry up to 50 billion euros, factories were paid to destroy a gas they made in order to destroy it, and a Dubai company sought carbon rights over a tenth of Liberia.",
  out="Where the law sets a limit, permission to exceed it becomes something to buy. The other way to deal with a limit is to move the harm to a place the limit does not reach, which is the next chapter.",
  roles=["Where the market is run or the buyer is based", "Where the credits came from"],
  steps=[
   S("2008 to 2019", "Brussels", "Europe: Permits Given Away Free", "Regional Example: The European Union opened the world's first large carbon market in 2005. Power plants and factories must hold one allowance for every tonne of carbon dioxide they release. Steel, cement, chemical and oil refining companies argued that if they had to buy allowances they would move production abroad. So they were given most of theirs free. Many received more than they needed and sold the surplus. Others raised their prices as if they had paid for the allowances. A study by the consultancy CE Delft estimated that between 2008 and 2019 heavy industry in 19 countries gained up to 50 billion euros this way. A system described to the public as making polluters pay had, for these industries, paid the polluter.", "https://carbonmarketwatch.org/publications/additional-profits-of-sectors-and-firms-from-the-eu-ets/",
     add={"Belgium": 0}, pins=[("Brussels", "EU Emissions Trading System")], pl=["eu_env", "businesseurope", "cefic", "ieta", "basf"], ex=["ets"], reg=True, z=3.2),
   S("2005 to 2013", "Bonn", "Credits for Destroying a Gas Made to Be Destroyed", "The Kyoto Protocol let rich countries meet part of their targets by paying for emission cuts in poorer ones, through a scheme run from the climate office in Bonn. One of the cheapest ways to earn credits was to burn off HFC-23, a waste gas from making refrigerant chemicals that warms the planet thousands of times more than carbon dioxide. Destroying it cost very little, and the credits were worth far more than the refrigerant itself. Most such projects were in China and India. Evidence emerged that some plants were producing more of the waste gas than they needed to, in order to be paid for destroying it. The European Union stopped accepting these credits in 2013.", "https://unfccc.int/process-and-meetings/the-kyoto-protocol/mechanisms-under-the-kyoto-protocol/the-clean-development-mechanism",
     add={"Germany": 0, "China": 1, "India": 1}, arcs=[("Beijing", "Bonn"), ("New Delhi", "Bonn"), ("Bonn", "Brussels")], pins=[("Bonn", "Clean Development Mechanism")], pl=["unfccc", "mee_cn", "moefcc", "eu_env"]),
   S("2023", "Monrovia", "Liberia: A Tenth of a Country", "Regional Example: The newest carbon deals are for land. In 2023 a draft agreement between the government of Liberia, in West Africa, and a company called Blue Carbon became public. Blue Carbon had been founded in Dubai the year before and is chaired by a member of Dubai's ruling family. The draft gave it exclusive rights for 30 years to generate and sell carbon credits from about one million hectares of forest, around a tenth of Liberia's land area. The company announced similar plans with several other African countries. Liberian organisations objected that communities who own much of that forest under Liberian law had not been asked. The buyer in such a deal gains the right to keep emitting elsewhere.", "https://news.mongabay.com/2023/08/liberia-set-to-concede-forestland-to-uae-firm-in-carbon-offset-deal/",
     add={"Liberia": 1, "United Arab Emirates": 0}, arcs=[("Dubai", "Monrovia")], pins=[("Monrovia", "Liberia"), ("Dubai", "Blue Carbon")], pl=["verra"], ex=["liberia"], reg=True),
  ],
  src=[{"t": "Carbon Market Watch", "u": "https://carbonmarketwatch.org/"}])

F(id="export", part=4, title="Sending Abroad What the Law Forbids at Home",
  kick="When a rich country bans a waste or a chemical, the trade moves it to a country where the ban does not apply.",
  sum="Environmental law stops at a border. A rule passed in one country applies only there. So when a country bans a dangerous substance or makes waste expensive to dispose of safely, one response is to send it somewhere the rule does not reach.<br><br>This has been understood since the 1980s, when barrels of toxic waste from Europe and North America were found dumped in African and Caribbean countries. The Basel Convention of 1989 was written to control that trade. It requires the receiving country's consent before hazardous waste is shipped to it. The United States has never joined.<br><br>The trade continued in other forms. Waste is relabelled as goods for recycling or reuse. A ship at the end of its life is sold to a broker and sails to a beach under a new flag. A pesticide banned at home stays legal to manufacture for export. In each case a strict rule in a rich country and the absence of one in a poor country are two halves of the same business. The saving is the difference in cost between the two.<br><br>This is why national figures can mislead. Chapter 1 showed emissions falling in some rich countries. Part of that fall is production, and waste, that moved.",
  bridge="The first slide is the treaty written to stop the trade. The next four each follow one kind of cargo from where it was made to where it ended up: toxic sludge, plastic waste, pesticides banned in Europe, and old ships.",
  rec="A trader's waste was dumped in Abidjan, Europe's plastic moved to Southeast Asia and Turkey, 81,000 tonnes of banned pesticides were exported in a year, and most old ships are broken on South Asian beaches.",
  out="The harm that the law forbids in one country is sold to another. The next part goes to the places at the end of every chain described so far, and to the people who live in them.",
  roles=["Where it was sent from", "Where it was sent to"],
  steps=[
   S("1989", "Geneva", "A Treaty Against Dumping, Without Its Largest Producer", "In the late 1980s a series of scandals showed that companies in rich countries were paying to have hazardous waste shipped to poorer ones. Governments responded with the Basel Convention, agreed in the Swiss city of Basel in 1989 and run from an office in Geneva. Under it, hazardous waste may cross a border only if the receiving government has been told what it is and has agreed. An amendment that bans rich countries from exporting such waste to poorer ones took effect in 2019. Almost every country has joined. The United States, which produces more waste per person than nearly any other, signed in 1990 and has never ratified. The following slides show what continued under the treaty.", "https://www.basel.int/",
     add={"Switzerland": 0}, arcs=[("Basel", "Geneva")], pins=[("Geneva", "Basel Convention office"), ("Basel", "Signed here, 1989")], pl=["brs", "unep"], z=3.4),
   S("2006", "Abidjan", "Abidjan: The Cheaper Port", "Regional Example: In 2006 the commodity trader Trafigura had a cargo of cheap, dirty petrol stock cleaned on board a ship, the Probo Koala, by a process that leaves a toxic, foul-smelling sludge. The ship went to Amsterdam to unload it. When the treatment company there saw what the waste was, it raised its price sharply. The ship took the waste back on board and sailed to Abidjan, the largest city in Côte d'Ivoire, where a newly formed local company agreed to take it for a small fraction of the cost. It was dumped at about a dozen open sites around the city in August. Tens of thousands of people sought medical treatment and the authorities recorded deaths. Trafigura paid the Ivorian state about 198 million dollars and admitted no liability.", "https://www.amnesty.org/en/documents/afr31/002/2012/en/",
     add={"Netherlands": 0, "Cote d'Ivoire": 1}, arcs=[("Amsterdam", "Abidjan")], pins=[("Abidjan", "Waste dumped, August 2006"), ("Amsterdam", "Unloading refused")], pl=["trafigura", "brs"], ex=["probo"], reg=True),
   S("2018", "Beijing", "Plastic: When China Closed the Door", "For decades rich countries shipped much of the plastic their households put out for recycling to China. In January 2018 China banned imports of most plastic waste. The waste did not stop being produced. Within months the shipments had been redirected, mainly to Malaysia, Vietnam, Thailand and Indonesia, and later to Turkey. Those countries had far less capacity to process it, and investigators found imported plastic burned in the open or dumped. Several of them then brought in restrictions of their own. Plastic waste was added to the Basel Convention's controls in 2021. The episode showed that a good part of what rich countries counted as recycling had been export.", "https://www.basel.int/Implementation/Plasticwaste/Overview/tabid/8347/Default.aspx",
     add={"United States": 0, "United Kingdom": 0, "Germany": 0, "Japan": 0, "China": 1, "Malaysia": 1, "Vietnam": 1, "Thailand": 1, "Indonesia": 1, "Turkiye": 1}, arcs=[("Washington", "Kuala Lumpur"), ("London", "Ankara"), ("Berlin", "Kuala Lumpur"), ("Tokyo", "Bangkok"), ("Tokyo", "Hanoi"), ("London", "Jakarta")], pins=[("Beijing", "Import ban, January 2018"), ("Kuala Lumpur", "Malaysia"), ("Ankara", "Turkey")], pl=["mee_cn", "brs", "acc"], w=0, z=1.4),
   S("2018", "Brussels", "Pesticides: Banned on the Farm, Legal to Export", "The European Union bans a pesticide when it finds the danger to health or wildlife too great. The ban covers use inside the Union. It does not cover making the chemical there and selling it elsewhere. Two investigative groups obtained the export paperwork for 2018. It showed that companies in European countries, including the United Kingdom, which was then still covered by the Union's rules, had notified exports of 81,615 tonnes of pesticides containing 41 banned chemicals. The largest single product was paraquat, a weedkiller made by Syngenta at a factory in Huddersfield, England. The main destinations included Brazil, Ukraine, Morocco, Mexico and South Africa. The danger that justified the ban is the same wherever the chemical is sprayed.", "https://www.publiceye.ch/en/topics/pesticides/banned-in-europe",
     add={"United Kingdom": 0, "Italy": 0, "Germany": 0, "Netherlands": 0, "France": 0, "Spain": 0, "Belgium": 0, "Brazil": 1, "Ukraine": 1, "Morocco": 1, "Mexico": 1, "South Africa": 1}, arcs=[("Huddersfield", "Brasília"), ("Huddersfield", "Mexico City"), ("Rome", "Rabat"), ("Berlin", "Kyiv"), ("Paris", "Brasília"), ("Brussels", "Pretoria")], pins=[("Huddersfield", "Paraquat factory"), ("Basel", "Syngenta")], pl=["syngenta", "bayer", "basf", "croplife", "publiceye", "eu_env"], ex=["pesticides"], w=0, z=1.5),
   S("Every year", "Chittagong", "Ships: Broken on the Beach", "A large ship contains asbestos, oil residues and heavy metals, and taking one apart safely in a dock is expensive. Most are not taken apart that way. When a ship reaches the end of its working life, its owner usually sells it to a cash buyer, a broker who re-registers it under a different flag for its last voyage. It is then run aground at high tide on a beach at Alang in India, Chittagong in Bangladesh or Gadani in Pakistan, and cut up by hand where it lies. Alang alone handles about 30 per cent of the world total. The owners are mostly in Greece, China and Germany and other shipping nations. The oil and metals go into the sand and sea, and workers are killed every year.", "https://shipbreakingplatform.org/",
     add={"Greece": 0, "Germany": 0, "China": 0, "India": 1, "Bangladesh": 1, "Pakistan": 1}, arcs=[("Hamburg", "Alang"), ("Hamburg", "Chittagong"), ("Beijing", "Chittagong"), ("London", "Gadani")], pins=[("Alang", "Alang"), ("Chittagong", "Chittagong"), ("Gadani", "Gadani")], pl=["shipbreaking", "imo", "ics"], w=0, z=1.6),
  ],
  src=[{"t": "Basel Convention", "u": "https://www.basel.int/"}, {"t": "NGO Shipbreaking Platform", "u": "https://shipbreakingplatform.org/"}])

F(id="zones", part=5, title="Sacrifice Zones",
  kick="Places where pollution was permitted to concentrate until the people living there became ill.",
  sum="Every chain on this map ends somewhere. The treaty without a penalty, the permit, the absent inspector, the waste sent abroad: each has an address where its results arrive. This part of the story goes to those addresses.<br><br>The United Nations' independent expert on human rights and the environment gave them a name in a 2022 report: sacrifice zones. The term describes a place where the people living nearby suffer severe illness and shortened lives because of pollution from industry around them. Somebody, at some point, decided that this place and these people could be given up in exchange for what the industry produces. The decision is rarely stated. It is made through a series of permits.<br><br>These zones have features in common. The residents are usually poor, and often belong to a group with little political power: an Indigenous people, a racial minority, migrant workers. The industry is usually legal and licensed. Residents have often complained for decades. And the goods produced, whether metal, fuel or plastic, are mostly used somewhere else.<br><br>They are included here for what they show about the law. If environmental law worked as most people assume, such places could not exist. They are the measure of the gap.",
  bridge="The first slide gives the worldwide toll and marks the zones the United Nations expert named. The next three visit individual places, in Italy, Peru and Russia, where a court or an official body has confirmed what residents had been saying.",
  rec="Pollution kills about nine million people a year; the UN has named sacrifice zones on every continent, and human rights courts have ruled for the people of Taranto and La Oroya.",
  out="These are the places the law gave up. In many of them people organised to ask for the law to be applied, and the next chapter records what happened to some of those people.",
  roles=["A place named as a sacrifice zone"],
  steps=[
   S("2022", "Geneva", "Nine Million Deaths, and the Places Named", "In 2022 a commission of scientists writing in the medical journal The Lancet estimated that pollution causes about nine million early deaths a year. That is one death in six worldwide, more than war, malaria and tuberculosis together. In the same year the United Nations expert presented a report in Geneva naming sacrifice zones around the world. The map marks some of those listed: Kabwe in Zambia, poisoned by a lead mine; La Oroya in Peru; Norilsk in Arctic Russia; Quintero and Puchuncaví on the coast of Chile; Bor in Serbia; Taranto in Italy; and the stretch of Louisiana from chapter 5. Each of these sites operated for decades with the knowledge of its government.", SZ,
     add={"Zambia": 0, "Peru": 0, "Russia": 0, "Chile": 0, "Serbia": 0, "Italy": 0, "United States": 0}, pins=[("Kabwe", "Kabwe"), ("La Oroya", "La Oroya"), ("Norilsk", "Norilsk"), ("Quintero", "Quintero-Puchuncaví"), ("Bor", "Bor"), ("Taranto", "Taranto"), ("St James Parish", "Cancer Alley")], pl=["ohchr"], ex=["sacrifice", "lancet"], w=0, z=1.3),
   S("2012 to 2019", "Taranto", "Italy: Decrees to Keep the Furnaces Lit", "Regional Example: Taranto, a port city in southern Italy, was home to the largest steelworks in Europe. Studies found higher rates of cancer and of children's illness in the districts beside it. In 2012 Italian prosecutors ordered the most polluting parts of the plant seized and shut. The national government responded with a decree declaring the plant a site of strategic national interest so that it could keep operating, and passed further decrees in the years that followed, including one protecting its managers from prosecution. In 2019 the European Court of Human Rights ruled that Italy had failed to protect residents' health. Here the law that was written yielded to the law that was passed to override it.", "https://hudoc.echr.coe.int/eng?i=001-189645",
     add={"Italy": 0, "France": 0}, arcs=[("Taranto", "Strasbourg")], pins=[("Taranto", "Ilva steelworks"), ("Strasbourg", "European Court of Human Rights")], pl=["ecthr"], ex=["taranto"], reg=True, z=3.2),
   S("1922 to 2024", "La Oroya", "Peru: A Century at the Smelter", "Regional Example: La Oroya is a town high in the Peruvian Andes built around a smelter that has processed lead, copper and zinc since 1922. Health surveys found that almost every child tested there had lead in their blood above the level considered dangerous. Lead damages a growing brain permanently. The smelter passed from a United States company to the Peruvian state and, in 1997, to another United States company, and each owner was given more time to meet pollution limits. Residents took their case to the Inter-American human rights system in 2006. The court's judgment against Peru was published in March 2024. It found the state responsible because it had not regulated or supervised the plant.", "https://www.corteidh.or.cr/docs/casos/articulos/seriec_511_ing.pdf",
     add={"Peru": 0, "Costa Rica": 0}, arcs=[("La Oroya", "San José")], pins=[("La Oroya", "La Oroya smelter"), ("San José", "Inter-American Court")], pl=["iacthr"], ex=["laoroya"], reg=True),
   S("2020", "Norilsk", "Russia: A City Built Around the Smelters", "Regional Example: Norilsk lies north of the Arctic Circle in Siberia. It exists to serve the nickel, copper and palladium smelters of the company Nornickel, which for years made the city one of the largest single sources of sulphur dioxide pollution on Earth. In May 2020 a fuel tank at a company power plant collapsed and about 21,000 tonnes of diesel ran into rivers. Russia's environmental inspectorate claimed damages, and a court ordered the company to pay about 146 billion roubles, close to 2 billion dollars, the largest environmental penalty in Russian history. The company paid within weeks. The smelters, the main source of the city's pollution, continued to operate under their permits.", "https://www.reuters.com/article/us-russia-pollution-nornickel-idUSKBN2AA0ZL",
     add={"Russia": 0}, arcs=[("Moscow", "Norilsk")], pins=[("Norilsk", "Norilsk"), ("Moscow", "Nornickel")], pl=["nornickel", "rpn"], reg=True, z=2.2),
  ],
  src=[{"t": "UN Special Rapporteur, report on sacrifice zones, A/HRC/49/53", "u": SZ}])

F(id="defenders", part=5, title="The People Who Asked for the Law to Be Applied",
  kick="More than 2,300 people have been killed since 2012 for defending land and the environment.",
  sum="In a place where the regulator does not come and the court is out of reach, the work of protecting land and water falls to the people who live there. They hold meetings, file complaints, block roads and speak to journalists. The usual name for them is land and environmental defenders. Most would describe themselves more simply, as farmers, fishers, Indigenous leaders or mothers.<br><br>The organisation Global Witness has kept a count since 2012 of those who were killed for this work, or who disappeared. It records only cases it can confirm, so the true number is higher. The killings are concentrated where valuable resources lie under or on land whose ownership is disputed: mines, dams, plantations, cattle ranches and logging areas. Few are ever solved. Where there is a conviction it is usually of the gunman and not of whoever paid him.<br><br>These deaths belong in a map about law for a plain reason. The people killed were, in most cases, asking for laws already on the books to be applied: a consultation required by law, a title to land, a permit condition. Where the state does not enforce its own rules, those who insist on them are left exposed to whoever profits from the rules being ignored.",
  bridge="The first slide gives the count and where the killings happen. The next two tell what is known about two of the dead, in Honduras and Nigeria, including who was held responsible. The last maps the treaty written to protect such people, and which countries have declined to join it.",
  rec="At least 2,375 defenders have been killed or disappeared since 2012, most in Latin America; the treaty written to protect them lacks Brazil, Peru, Guatemala and Honduras.",
  out="This is the bottom of the chain. The final part of the story turns to the places where the chain was broken, and how.",
  roles=["Where the killings are concentrated or the defender lived", "Where the company or the treaty office is"],
  steps=[
   S("2012 to 2025", "Bogotá", "The Count Since 2012", "Global Witness, an investigative organisation in London, has documented at least 2,375 killings and long-term disappearances of land and environmental defenders between 2012 and 2025. In 2025 it recorded at least 124. Latin America has been the most dangerous region in every year of the count, with 85 per cent of the 2025 cases. Colombia and Brazil together made up more than half. Forty-four of those killed in 2025 were Indigenous people, a far larger share than their part of the world's population. The organisation links the killings most often to disputes over land, and to mining, farming and logging. Behind each number is a person who had usually already reported threats to the authorities.", GW,
     add={"Colombia": 0, "Brazil": 0, "United Kingdom": 1}, pins=[("Bogotá", "Colombia"), ("Brasília", "Brazil"), ("London", "Global Witness")], pl=["globalwitness"], ex=["gw2025"], w=0, z=2.0),
   S("2016 to 2021", "La Esperanza", "Honduras: Berta Cáceres", "Regional Example: Berta Cáceres was a leader of the Lenca people of western Honduras. She led her community's opposition to the Agua Zarca dam, which was to be built on a river the Lenca hold sacred, without the consultation with them that Honduran and international law require. She reported dozens of threats. On the night of 2 March 2016 gunmen broke into her home in La Esperanza and shot her dead. Seven men were convicted in 2018, among them an employee of the dam company, DESA, and a serving army officer. In 2021 a court convicted Roberto David Castillo, who had been the company's president, of helping to plan the murder. International lenders had withdrawn from the dam after her death.", "https://www.theguardian.com/world/2021/jul/05/berta-caceres-assassination-roberto-david-castillo-found-guilty",
     add={"Honduras": 0}, arcs=[("Tegucigalpa", "La Esperanza")], pins=[("La Esperanza", "La Esperanza"), ("Tegucigalpa", "Trial court")], pl=["copinh"], ex=["berta"], reg=True, z=4.0),
   S("1995 to 2009", "Port Harcourt", "Nigeria: Ken Saro-Wiwa", "Regional Example: Ken Saro-Wiwa was a Nigerian writer and television producer from Ogoniland, the part of the Niger Delta described in chapter 14. In 1990 he helped found a movement that demanded a clean-up of the oil pollution and a share of the oil income for the Ogoni. In 1993 some 300,000 people marched, and Shell stopped pumping there. The military government arrested him and eight others, tried them before a special tribunal that international observers condemned, and hanged them in Port Harcourt on 10 November 1995. Relatives sued Shell in New York, alleging it had helped the government. Shell denied this and, in 2009, paid 15.5 million dollars to settle the case without admitting liability.", "https://ccrjustice.org/home/what-we-do/our-cases/wiwa-et-al-v-royal-dutch-petroleum-et-al",
     add={"Nigeria": 0, "United Kingdom": 1}, arcs=[("Bori", "Port Harcourt"), ("Port Harcourt", "New York")], pins=[("Port Harcourt", "Port Harcourt, 10 November 1995"), ("Bori", "Ogoniland")], pl=["shell", "nnpc"], ex=["sarowiwa", "ogoni"], reg=True),
   S("2018 to 2026", "Latin America and the Caribbean", "The Treaty That Protects Defenders, and Who Is Outside It", "In 2018 the countries of Latin America and the Caribbean adopted the Escazú Agreement, named after the Costa Rican town where it was concluded and serviced from Santiago, Chile. It gives people the right to environmental information, to take part in decisions and to go to court. It is also the first treaty anywhere to oblige governments to protect environmental defenders and to investigate attacks on them. The map shades the region's countries by whether they have joined. Nineteen have. Brazil, which has the second-highest count of killings, has signed but not ratified. Peru and Guatemala have not ratified either, and Honduras has not signed. Costa Rica, where the treaty was concluded, has not ratified it.", "https://www.cepal.org/en/escazuagreement",
     data={"k": "escazu", "only": "la"}, z=2.2, w=1),
  ],
  src=[{"t": "Global Witness, land and environmental defenders", "u": GW}])

F(id="pushback", part=6, title="Where the Law Was Made to Work",
  kick="A treaty with penalties, courts that enforced rights, and countries that walked away from bad agreements.",
  sum="Nothing described so far was inevitable. Each weakness in the chain was a choice, and in some places a different choice was made. This chapter gathers those cases. They are fewer than the failures, and several are incomplete or under challenge. They are included because they show which parts of the chain can be changed, and by whom.<br><br>They fall into a few kinds. One is a treaty designed with real consequences, as trade treaties are. Another is a court willing to treat a healthy environment as a right that belongs to people, and to order a government to act on it. A third is a constitution or law that gives nature standing of its own, so that the question in court is not how much harm to permit. A fourth is the public itself, through votes and protest, forcing a decision that neither the regulator nor the legislature would make. A fifth is governments leaving agreements that punish them for protecting the environment.<br><br>What these cases share is that someone other than the regulated industry held the pen or the gavel, and that there was a consequence for ignoring the result. The reader can test each earlier chapter against that.",
  bridge="The slides go from the international level down, in the same order as the story. They begin with the one treaty that worked, then the highest international court, then national courts in Europe and Ecuador, then a public uprising in Panama, and end with a river in New Zealand.",
  rec="The ozone treaty worked because it had penalties; the top courts of the Netherlands, Europe and the world ruled that governments must protect the climate; Ecuador and Panama stopped mines.",
  out="Each of these reversed one link in the chain. The last chapter puts the whole chain back together and asks what would have to change for these cases to stop being exceptions.",
  roles=["Where the law was made to work"],
  steps=[
   S("1987", "Montreal", "A Treaty That Worked", "Chapter 2 introduced the Montreal Protocol as the exception among environmental treaties. It is worth returning to because it is the proof that the others could have been written differently. Three features set it apart. Countries inside the treaty were forbidden to trade the controlled chemicals with countries outside it. A fund paid developing countries the extra cost of changing technology. And the list of controlled chemicals was tightened repeatedly as the science developed. All 198 parties have ratified it, and about 98 per cent of the chemicals have been phased out. The ozone layer is recovering. The chemical industry opposed the treaty at first, then found it could sell the replacements.", "https://ozone.unep.org/treaties/montreal-protocol",
     add={"Canada": 0, "Kenya": 0}, arcs=[("Montreal", "Nairobi")], pins=[("Montreal", "Montreal Protocol, 1987")], pl=["ozone", "unep"]),
   S("2025", "The Hague", "The World's Highest Court Is Asked", "In 2019 a group of law students at a university in the Pacific began a campaign to ask the International Court of Justice a question: what do countries owe one another, and future generations, in protecting the climate? The government of Vanuatu, an island nation threatened by rising seas, took the idea to the United Nations, and in 2023 the General Assembly sent the question to the court without a single country voting against. On 23 July 2025 the court gave its answer unanimously. Countries have legal duties to protect the climate. Those duties include controlling private companies. Subsidising and licensing fossil fuels can be an unlawful act for which a country owes repair. Courts everywhere may now cite this.", "https://www.icj-cij.org/case/187",
     add={"Netherlands": 0, "Vanuatu": 0}, arcs=[("Port Vila", "New York"), ("New York", "The Hague")], pins=[("The Hague", "International Court of Justice"), ("Port Vila", "Vanuatu")], pl=["icj"], ex=["icj_ao"]),
   S("2019 to 2024", "Strasbourg", "Europe: Courts That Ordered Governments to Act", "Regional Example: In December 2019 the Supreme Court of the Netherlands upheld a ruling won by the Urgenda Foundation and 900 citizens. It ordered the Dutch government to cut emissions by at least 25 per cent from 1990 levels by the end of 2020, on the ground that failing to do so endangered citizens' rights to life and family life. The government closed coal capacity to comply. In April 2024 the European Court of Human Rights applied the same reasoning to a case brought by a group of older Swiss women, ruling that Switzerland had violated their rights by not doing enough on climate. That court's rulings bind 46 countries. In both cases the obstacle of standing from chapter 13 was overcome.", "https://www.urgenda.nl/en/themas/climate-case/",
     add={"Netherlands": 0, "France": 0, "Switzerland": 0}, arcs=[("Amsterdam", "The Hague"), ("Bern", "Strasbourg")], pins=[("The Hague", "Urgenda ruling, 2019"), ("Strasbourg", "KlimaSeniorinnen ruling, 2024")], pl=["urgenda", "hague_ct", "ecthr"], ex=["urgenda_x"], reg=True, z=3.4),
   S("2021 to 2023", "Quito", "Ecuador: The Forest Has Rights", "Regional Example: In 2008 Ecuador adopted a constitution that gives nature itself the right to exist and to be restored. For years the clause had little effect. In November 2021 the Constitutional Court applied it to Los Cedros, a cloud forest north of Quito that is home to rare monkeys, frogs and orchids, where the state mining company and a Canadian partner held permits to explore for copper and gold. The court cancelled the permits. In August 2023 Ecuadorians voted in a national referendum, by about 59 per cent, to halt oil drilling in a block of Yasuní National Park in the Amazon. Carrying out the vote has been slow, which echoes chapter 14, but the legal question was settled by the public.", "https://www.corteconstitucional.gob.ec/",
     add={"Ecuador": 0}, arcs=[("Los Cedros", "Quito"), ("Yasuní", "Quito")], pins=[("Los Cedros", "Los Cedros forest"), ("Yasuní", "Yasuní National Park"), ("Quito", "Constitutional Court")], pl=["cc_ec"], ex=["loscedros"], reg=True, z=4.2),
   S("2023", "Panama City", "Panama: A Country Says No", "Regional Example: Cobre Panamá is an open-pit copper mine cut into rainforest on Panama's Caribbean side, owned by the Canadian company First Quantum Minerals. In October 2023 Panama's legislature approved a new 20-year contract for it in a matter of days. The response was the largest protest movement the country had seen in decades. For more than a month, teachers, students, construction workers, fishers and Indigenous groups blocked roads and ports. On 28 November the Supreme Court ruled unanimously that the contract violated the constitution, and the president announced the mine would close. The company then filed arbitration claims seeking billions of dollars, using the system from chapter 4.", "https://www.reuters.com/world/americas/panama-top-court-rules-first-quantum-mining-contract-unconstitutional-2023-11-28/",
     add={"Panama": 0}, arcs=[("Cobre Panamá", "Panama City"), ("Toronto", "Cobre Panamá")], pins=[("Cobre Panamá", "Cobre Panamá mine"), ("Panama City", "Supreme Court")], pl=["fqm", "icsid"], ex=["panama"], reg=True),
   S("2017", "Whanganui", "New Zealand: A River as a Legal Person", "Regional Example: The Whanganui is the third-longest river in New Zealand. The Māori tribes who live along it had argued in petitions and courts since the 1870s that the river is an ancestor and an indivisible whole, not a resource to be divided and used. In 2017, as part of a settlement of that claim, the New Zealand Parliament passed a law recognising the river as a legal person with its own rights and duties. Two guardians, one appointed by the tribes and one by the government, speak for it. The settlement ended the longest-running court dispute in the country's history. It answers the standing problem directly: the river itself can now be the one that goes to court.", "https://www.legislation.govt.nz/act/public/2017/0007/latest/whole.html",
     add={"New Zealand": 0}, arcs=[("Wellington", "Whanganui")], pins=[("Whanganui", "Whanganui River"), ("Wellington", "Parliament")], pl=[], reg=True, z=4.0),
  ],
  src=[{"t": "UN Environment Programme, Global Climate Litigation Report", "u": "https://www.unep.org/resources/report/global-climate-litigation-report-2023-status-review"}])

F(id="whole_chain", part=6, title="The Whole Chain, and What It Has Not Limited",
  kick="From the treaty to the permit to the place where the pollution lands, followed once more from the top.",
  sum="The story began with a puzzle. Since 1972 the world has written environmental laws at a rate never seen before, and in the same years the damage those laws address has grown. Nineteen chapters later the puzzle can be answered plainly.<br><br>The laws were written inside a chain in which the industries to be regulated are present at every link. At the top, they attend the treaty talks in greater numbers than most countries, and the treaties that result have no penalties, while treaties that protect investors do. At the level of the state, governments license pollution, subsidise it, repeal rules that cost money and hire few inspectors. The text of laws and standards is often drafted by those they apply to, and regulators are drawn from the same industries. Courts are hard to enter and slow to deliver. Markets have been built to sell permission and to carry the harm across borders. At the bottom are the places and the people who were given up.<br><br>None of this required a conspiracy. It required only that at each link, the party with the most money at stake was also the party with the most access. The pushback chapter showed what happens when that is not the case. This last chapter draws the chain once more in a single view.",
  bridge="Three slides close the story. The first redraws the chain from the top to the ground. The second gives the single figure that best measures the outcome. The third returns to the reader, and to what the cases in the previous chapter had in common.",
  rec="",
  out="The chain is long, and it is made of decisions. Each of them was taken by people, in rooms that can be named and are named on this map. The laws exist. The question the map leaves with the reader is who is in the room when they are written, and who is there when they are supposed to be applied.",
  roles=["A point on the chain"],
  steps=[
   S("1972 to 2026", "From the top down", "The Chain, in One View", "Follow it once more. In Nairobi, Bonn and Geneva, treaties are serviced that carry no penalty. At the summits where they are negotiated, in Dubai, Baku and Belém, fossil fuel lobbyists outnumber almost every country. In Washington, an arbitration centre lets investors sue governments for regulating. In national capitals, ministries issue permits, treasuries pay subsidies and legislatures remove rules inside budget bills. In Arlington, Calgary and Brussels, trade associations draft and lobby. In Geneva, Washington and Munich, private bodies certify. The waste travels to Abidjan and Chittagong. And at Taranto, La Oroya, Bori and St James Parish, the result arrives. Every line drawn in the earlier chapters is on this slide.", UNEP19,
     arcs=[("Nairobi", "Bonn"), ("Bonn", "Belém"), ("Washington", "Brussels"), ("Arlington", "Washington"), ("Calgary", "Ottawa"), ("Geneva", "Brumadinho"), ("Amsterdam", "Abidjan"), ("Hamburg", "Chittagong"), ("London", "Bori"), ("Baton Rouge", "St James Parish")],
     pins=[("Nairobi", "The agency"), ("Belém", "The summit"), ("Washington", "The investors' court"), ("Brussels", "The lobby"), ("Abidjan", "The waste"), ("Bori", "The ground")], pl=["unep", "unfccc", "icsid", "alec", "capp", "iso", "trafigura", "shell"], w=1, z=1.2),
   S("1972 to 2025", "The whole world", "Three-Quarters of It Came After the Laws", "One number sums up the outcome. Add together all the carbon dioxide that humanity has released from coal, oil, gas and cement since the start of the industrial age. About 77 per cent of it has been released since 1972, the year of the Stockholm conference and the start of modern environmental law. More than half has been released since 1992, the year the climate convention was signed. The period in which the world had environmental ministries, treaties, impact assessments and summits is the period in which most of the damage was done. The laws did not prevent it. As earlier chapters showed, in important ways they organised it: they issued the permits.", "https://github.com/owid/co2-data",
     data={"k": "co2_1972", "only": None}, z=1.15, w=1),
   S("Now", "Where you live", "What the Exceptions Had in Common", "The cases in the last chapter were not luck. In each one, three things were true. People outside the industry had the right to know what was being released and decided. They had a way into the room or the court. And there was a real consequence when the result was ignored: a trade ban, a binding order, a contract struck down. The ozone treaty had all three and worked. The Aarhus Convention in Europe and the Escazú Agreement in Latin America write the first two into law for the countries that have joined them. Wherever you live, the organisations on this map can be looked up, the permits near you are public documents in most countries, and the rooms have addresses.", "https://unece.org/environment-policy/public-participation/aarhus-convention/introduction",
     arcs=[("Geneva", "Santiago")], pins=[("Geneva", "Aarhus Convention"), ("Santiago", "Escazú Agreement")], pl=["aarhus", "escazu", "ejatlas", "clientearth", "earthjustice", "sabin"], w=1, z=1.2),
  ],
  src=[{"t": "Global Carbon Budget, via Our World in Data", "u": "https://github.com/owid/co2-data"}])

GLOSS = {
 "UNEP": "The United Nations Environment Programme, the UN body for the environment, based in Nairobi since 1972.",
 "COP": "Conference of the Parties: the yearly meeting of the countries that have joined a treaty. The climate COPs are the best known.",
 "secretariat": "The small permanent office of a treaty. It organises meetings and collects countries' reports, and has no power to enforce.",
 "ratified": "Formally approved by a country, usually by its legislature, so that a treaty it has signed becomes binding on it.",
 "ratify": "To approve a signed treaty formally, usually in the legislature, so that it becomes binding on the country.",
 "nationally determined contribution": "The climate pledge each country writes for itself under the Paris Agreement. No one can force a country to strengthen or meet it.",
 "consensus": "A way of deciding in which nothing passes if any country formally objects, so one country can block all the others.",
 "lobbyist": "A person paid to influence a law, a rule or a decision on behalf of a company or an industry.",
 "trade association": "An organisation funded by the companies in one industry to speak for all of them to governments and the public.",
 "ISDS": "Investor-state dispute settlement: the right, written into investment treaties, for a foreign company to sue a government before private arbitrators.",
 "arbitrators": "Private individuals, usually lawyers, chosen by the two sides to decide a dispute in place of a public court.",
 "sunset clause": "A term in a treaty that keeps its protections alive for a set time after a country leaves. In the Energy Charter Treaty it is 20 years.",
 "regulatory chill": "The effect on a government that holds back from a new rule because it fears being sued over it.",
 "Energy Charter Treaty": "A 1994 treaty that lets energy investors sue the governments that have signed it. The European Union left it in 2025.",
 "permit": "Official permission to do something that would otherwise be unlawful, such as releasing a set amount of a pollutant.",
 "environmental impact assessment": "A study of the damage a proposed project is expected to cause, required before approval in most countries and usually paid for by the developer.",
 "natural resource rents": "The income a country earns from oil, gas, coal, minerals and forests above what it costs to extract them.",
 "subsidy": "Public support, in money or in costs left unpaid, that makes something cheaper to produce or buy than it would otherwise be.",
 "implicit": "Not paid out directly. An implicit subsidy is a cost, such as illness from air pollution, that a product's price leaves the public to bear.",
 "regulation": "A detailed rule written by a government agency under powers given by a law. It can usually be changed without a vote in the legislature.",
 "omnibus": "A single bill that changes many unrelated laws at once, which leaves little time to debate any one change.",
 "endangerment finding": "The 2009 decision by the US Environmental Protection Agency that greenhouse gases endanger public health, which obliged it to regulate them. It was cancelled in 2026.",
 "due diligence": "A legal duty on a company to look for harm in its own operations and supply chain, and to deal with what it finds.",
 "self-monitoring": "An arrangement in which the company measures its own pollution and reports the figures to the regulator.",
 "model bill": "A ready-drafted law that an organisation offers to legislators in many places, with a blank for the name of the state or country.",
 "revolving door": "The movement of people between jobs in an industry and jobs in the government bodies that regulate it.",
 "levy": "A charge that a government or regulator collects from a particular group, here from the companies being regulated.",
 "standing": "The right to bring a case. A court will hear only someone who can show a particular harm, caused by the defendant, that a ruling could repair.",
 "SLAPP": "Strategic lawsuit against public participation: a case brought mainly to burden a critic with legal costs, whether or not it can be won.",
 "subsidiary": "A company owned by another company. In law it is a separate person, so its parent is not automatically liable for what it does.",
 "liable": "Legally responsible for a harm, and so required to repair or pay for it.",
 "allowance": "A permit to release one tonne of carbon dioxide under a carbon market.",
 "carbon credit": "A certificate saying that one tonne of carbon dioxide was kept out of the air somewhere, which the buyer may count against its own emissions.",
 "offsetting": "Paying for a reduction in emissions elsewhere and counting it as one's own.",
 "carbon neutral": "A claim that a company's emissions have been cancelled out, usually by buying carbon credits.",
 "Basel Convention": "The 1989 treaty that requires a country's consent before hazardous waste is shipped to it.",
 "flag state": "The country where a ship is registered and whose law it sails under. Owners may register in a country they have no other link to.",
 "open registries": "Countries that register ships owned by foreigners for a fee, also called flags of convenience.",
 "tailings": "The mud of crushed rock, water and chemicals left over after metal has been taken out of ore, usually stored behind a dam.",
 "sacrifice zones": "Places where residents suffer severe harm to health because of heavy pollution from industry around them. The term is used by the UN's human rights experts.",
 "defenders": "People who act peacefully to protect land, water or the environment where they live.",
 "rights of nature": "A legal approach in which a forest, a river or nature as a whole holds rights of its own that a court can enforce.",
 "advisory opinion": "A formal answer by an international court to a legal question. It is not an order, but other courts treat it as authoritative.",
 "Escazú Agreement": "The 2018 Latin American and Caribbean treaty on environmental information, participation and justice, and the first to require protection of environmental defenders.",
 "Aarhus Convention": "The 1998 treaty giving people in Europe and Central Asia rights to environmental information, participation and access to courts.",
 "plagiarised": "Copied from someone else's text and presented as one's own.",
}
